    for d, f, t, c in flights:
        if f == 0:
            graph[t].append((d, c))
        else:
            graph[f].append((d, c))

    def dijkstra(start):
        distances = defaultdict(lambda: float('inf'))
        distances[start] = 0
        pq = [(0, start)]

