from heapq import heappop, heappush
from collections import defaultdict
import sys

def solve_olympiad(n, m, k, flights):
    graph_out = defaultdict(list)
    graph_in = defaultdict(list)

    for d, f, t, c in flights:
        if f == 0:
            graph_out[0].append((d, t, c))
        elif t == 0:
            graph_in[0].append((d, f, c))
        elif f < t:
            graph_out[f].append((d, t, c))
        else:
            graph_in[t].append((d, f, c))

    def dijkstra(graph, start):
        dist = defaultdict(lambda: float('inf'))
        dist[start] = 0
        priority_queue = [(0, start)]
        while priority_queue:
            current_dist, current_city = heappop(priority_queue)
            if current_dist > dist[current_city]:
                continue
            for dep_day, target_city, cost in graph[current_city]:
                if dep_day >= current_dist:
                    new_dist = dep_day + 1
                    if new_dist < dist[target_city]:
                        dist[target_city] = new_dist
                        heappush(priority_queue, (new_dist, target_city))
        return dist

    def calculate_cost(dist, target_city, k):
        if dist[target_city] == float('inf'):
            return float('inf')
        arrival_day = dist[target_city] - 1
        if arrival_day >= k:
            return 0
        return float('inf')

    out_to_zero = dijkstra(graph_out, 0)
    in_to_zero = dijkstra(graph_in, 0)

    min_cost = float('inf')

    for i in range(1, n + 1):
        out_cost = calculate_cost(out_to_zero, i, k)
        in_cost = calculate_cost(in_to_zero, i, k)
        if out_cost == float('inf') or in_cost == float('inf'):
            continue
        for _, _, cost in graph_out[i]:
            total_cost = out_cost + in_cost + cost
            min_cost = min(min_cost, total_cost)

    return -1 if min_cost == float('inf') else min_cost

def main():
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])
    k = int(data[2])
    flights = []

    index = 3
    for _ in range(m):
        d = int(data[index])
        f = int(data[index + 1])
        t = int(data[index + 2])
        c = int(data[index + 3])
        flights.append((d, f, t, c))
        index += 4

    result = solve_olympiad(n, m, k, flights)
    print(result)

if __name__ == "__main__":
    main()
